package io.openaev.database.model;import com.fasterxml.jackson.annotation.JsonProperty;import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import lombok.Getter;import lombok.Setter;@Getter@Setterpublic class ChainingRateLimit {  @JsonProperty("chaining_enable_rate_limit")  private boolean isRateLimit;  @JsonProperty("chaining_max_attempts")  @Max(99)  @Min(1)  private Integer maxAttempts;  @JsonProperty("chaining_max_temporal_rate")  @Max(59)  @Min(1)  private Integer maxTemporalRateInSeconds;}